<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, type UploadRequestOptions } from 'element-plus'
import { ArrowLeft, Check, Picture, Promotion } from '@element-plus/icons-vue'
import { apiMessage, blogApi } from '@blog/api'
import type { Category, PostInput, PostStatus } from '@blog/types'
const route = useRoute(); const router = useRouter(); const id = computed(() => String(route.params.id || '')); const loading = ref(Boolean(id.value)); const saving = ref(false); const categories = ref<Category[]>([])
const form = reactive<PostInput>({ title: '', slug: '', excerpt: '', content: '', coverImageUrl: '', status: 'draft', categoryId: '', tags: [] })
async function save(status: PostStatus) { if (!form.title.trim() || !form.content.trim()) { ElMessage.warning('标题和正文不能为空'); return }; saving.value = true; try { form.status = status; id.value ? await blogApi.updatePost(id.value, form) : await blogApi.createPost(form); ElMessage.success(status === 'published' ? '文章已发布' : '草稿已保存'); await router.replace('/blog/posts') } catch (error) { ElMessage.error(apiMessage(error, '保存失败')) } finally { saving.value = false } }
async function upload(options: UploadRequestOptions) { try { const media = await blogApi.upload(options.file); form.coverImageUrl = media.url; options.onSuccess(media); ElMessage.success('封面上传成功') } catch (error) { ElMessage.error(apiMessage(error, '上传失败')); throw error } }
onMounted(async () => { try { categories.value = await blogApi.categories(); if (id.value) Object.assign(form, await blogApi.post(id.value)) } catch (error) { ElMessage.error(apiMessage(error, '文章加载失败')) } finally { loading.value = false } })
</script>
<template><div v-loading="loading" class="blog-editor"><header><el-button text :icon="ArrowLeft" aria-label="返回" @click="router.push('/blog/posts')" /><div><strong>{{ id ? '编辑文章' : '新建文章' }}</strong><small>支持 Markdown 正文</small></div><span /><el-button :icon="Check" :loading="saving" @click="save('draft')">保存草稿</el-button><el-button type="primary" :icon="Promotion" :loading="saving" @click="save('published')">发布</el-button></header><div class="blog-editor-layout"><section class="blog-editor-main"><el-input v-model="form.title" class="blog-title-input" maxlength="180" placeholder="文章标题" /><el-input v-model="form.excerpt" type="textarea" :rows="2" maxlength="500" show-word-limit placeholder="内容摘要" /><el-input v-model="form.content" class="blog-content-input" type="textarea" resize="none" placeholder="使用 Markdown 开始写作..." /></section><aside class="blog-editor-settings"><h2>发布设置</h2><el-form label-position="top"><el-form-item label="URL 标识"><el-input v-model="form.slug" placeholder="留空时根据标题生成" /></el-form-item><el-form-item label="分类"><el-select v-model="form.categoryId" clearable placeholder="未分类"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="标签"><el-select v-model="form.tags" multiple filterable allow-create default-first-option :multiple-limit="10" placeholder="输入后回车" /></el-form-item></el-form><h2>封面图片</h2><el-upload class="blog-cover-upload" :show-file-list="false" accept="image/jpeg,image/png,image/gif,image/webp" :http-request="upload"><img v-if="form.coverImageUrl" :src="form.coverImageUrl" alt="文章封面" /><div v-else><el-icon><Picture /></el-icon><span>选择图片</span><small>最大 5 MiB</small></div></el-upload><el-button v-if="form.coverImageUrl" link type="danger" @click="form.coverImageUrl = ''">移除封面</el-button></aside></div></div></template>
